#include <regex>
#include <unordered_map>

// Fonction de conversion Markdown vers HTML
std::string markdown_to_html(const std::string& markdown) {
    // Tableau de substitution pour les balises HTML
    const std::unordered_map<std::string, std::string> html_tags{
        {"#", "<h1>"},
        {"##", "<h2>"},
        {"###", "<h3>"},
        {"####", "<h4>"},
        {"#####", "<h5>"},
        {"######", "<h6>"},
        {"*", "<em>"},
        {"**", "<strong>"},
        {"`", "<code>"},
        {"\\[([^\\]]*)\\]\\(\\S*\\)", "<a href=\"$2\">$1</a>"},
        {"\\*\\*\\*\\S*", "<blockquote>$1</blockquote>"},
        {"\\>\\S*", "<p>$1</p>"}
    };

    // Expression régulière pour rechercher les balises Markdown
    const std::regex markdown_regex(R"(\A((?:[ #]+|\*\*?|`|\\[(?:[^\\]]|\\]{2})\\]|\\*\\*\\*|\>).*?\Z))");

    // Conversion du texte Markdown en HTML
    std::string html;
    std::smatch match;
    std::string::const_iterator start = markdown.begin();
    std::string::const_iterator end = markdown.end();
    while (std::regex_search(start, end, match, markdown_regex)) {
        std::string matched_text = match.str(1);
        std::string replacement;

        // Recherche des balises Markdown dans le texte et substitution par les balises HTML correspondantes
        for (const auto& html_tag : html_tags) {
            std::string markdown_tag = html_tag.first;
            std::string html_tag_open = html_tag.second;
            std::string html_tag_close = (html_tag.first == "\\" || html_tag.first == "#") ? "</h" + std::to_string(html_tag.first.length()) + ">" : "</" + html_tag.first + ">";
            std::string replacement_tag = std::regex_replace(matched_text, std::regex(markdown_tag), html_tag_open + html_tag_close);
            if (!replacement.empty()) {
                replacement = replacement_tag;
                break;
            }
        }

        html += replacement;
        start = match.position() + match.length();
    }

    return html;
}

int main() {
    std::string markdown = "## Titre h2\n"
                           "Texte avec un **mot en gras** et un *mot en italique*.\n"
                           "Un lien vers http://example.com et un autre [lien](http://example.com).\n"
                           "Un bloc de citation:\n"
                           "    Texte du bloc de citation.\n"
                           "Un paragraphe:\n"
                           "> Texte du paragraphe.";

    std::cout << markdown_to_html(markdown) << std::endl;

    return 0;
}
```

