    if event is InputEventMouseMotion and Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
        camera_rot_speed = event.relative

func _process(delta):
    $Camera.rotate_object_local(Vector3.UP, -camera_rot_speed.x * mouse_sensitivity)
    $Camera.rotate_object_local(Vector3.RIGHT, camera_rot_speed.y * mouse_sensitivity)
    camera_rot_speed = Vector2()

func _physics_process(delta):
