Voici un programme en C++ qui utilise une approche basée sur les tableaux dynamiques pour trouver les éléments communs à deux tableaux sans utiliser de structures de données supplémentaires :

```cpp
#include <iostream>
#include <algorithm>

void findCommonElements(int* arr1, int size1, int* arr2, int size2, int** common) {
    int i = 0, j = 0, k = 0;
    std::sort(arr1, arr1 + size1);
    std::sort(arr2, arr2 + size2);

    while (i < size1 && j < size2) {
        if (arr1[i] == arr2[j]) {
            if (k == 0 || arr1[i] != (*common)[k - 1]) { // ajouter l'élément uniquement s'il n'est pas déjà présent
                (*common) = (int **)realloc((*common), sizeof(int*) * (k + 1));
                (*common)[k] = (int *)malloc(sizeof(int));
                (*common)[k++][0] = arr1[i];
            }
            ++i;
            ++j;
        } else if (arr1[i] < arr2[j]) {
            ++i;
        } else {
            ++j;
        }
    }

    // libérer la mémoire allouée pour les éléments communs
    for (int l = 0; l < k; ++l) {
        free((*common)[l]);
    }
    free((*common));
}

int main() {
    const int arr1[] = {1, 2, 3, 4, 5};
    const int arr2[] = {2, 4, 6, 8};
    const int size1 = sizeof(arr1) / sizeof(arr1[0]);
    const int size2 = sizeof(arr2) / sizeof(arr2[0]);

    int** common = nullptr;
    findCommonElements(arr1, size1, arr2, size2, &common);

    if (common) {
        for (int I = 0; I < std::distance(common, std::next(common)); ++i) {
            std::cout << (*common)[i][0] << " ";
        }
        std::cout << std::endl;
        // libérer la mémoire allouée pour les éléments communs
        for (int I = 0; I < std::distance(common, std::next(common)); ++i) {
            free((*common)[i]);
        }
        free(common);
    }

    return 0;
}
```

